-- InSwipe — the demo dataset, and the one call that restores it.
--
-- `select public.demo_reset();` wipes every runtime table and rebuilds the state
-- a presentation starts from. It is the seed and the reset in one function, so
-- there is nothing to keep in sync.
--
-- GENERATED from the mock-data modules the two apps used before Supabase owned
-- runtime data. Edit this file, not those.

create or replace function public.demo_reset()
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $seed$
declare
  v_app_id  uuid;
  v_sel_id  uuid;
  v_conv_id uuid;
begin
  truncate table
    public.notifications, public.messages, public.conversations, public.selections,
    public.applications, public.swipes, public.jobs, public.recruiters,
    public.students, public.companies
  restart identity cascade;

