    ('nexora', 'Nexora Labs', 'N', '#4F46E5', 'linear-gradient(135deg,#4F46E5 0%,#7C6CF5 55%,#A78BFA 100%)', '/covers/nexora.svg', true, 'Building AI tools for 50,000+ developers in Asia.', 'Nexora Labs makes developer productivity software trusted by teams at Flipkart, Zepto and over 300 startups. We ship fast, design obsessively, and believe the best tools feel invisible. Series A backed, headquartered in Koramangala, Bangalore.', 'SaaS · Dev Tools', '51–200 employees', '2021', 'Bangalore, India', 'nexoralabs.io', array['Async-first', 'Ship weekly', 'Open source', 'No-meeting Fridays', 'Flat hierarchy']::text[], array['React', 'TypeScript', 'Node.js', 'PostgreSQL', 'Docker', 'AWS', 'Figma']::text[], '[{"name":"Rohan Mehta","role":"Engineering Lead","initial":"R"},{"name":"Priya Nair","role":"Senior Designer","initial":"P"},{"name":"Arjun Kapoor","role":"Product Manager","initial":"A"}]'::jsonb),
