  /* ---------------------------------- jobs ---------------------------------- */
  insert into public.jobs (id, company_id, title, role_category, location, work_mode, duration_months, stipend, about, responsibilities, required_skills, preferred_skills, department, employment_type, status, posted, deadline, in_student_deck, sort_order) values
    ('nexora-fe', 'nexora', 'Frontend Developer Intern', 'Frontend', 'Bangalore', 'Hybrid', 3, 20000, 'Nexora Labs is building the next generation of AI-powered developer tools used by over 50,000 engineers across India and Southeast Asia. You will join a fast-moving product team and work on features that ship to real users weekly.

As a Frontend Developer Intern you will collaborate directly with senior engineers and the design team to build polished, performant interfaces. This is a hands-on internship, not a shadow role.', array['Build and maintain React components for the core product dashboard, working from Figma designs.', 'Integrate REST APIs and manage client-side state.', 'Write unit and integration tests to keep frontend coverage above 80%.', 'Take part in daily standups, code review and sprint retrospectives.']::text[], array['React', 'JavaScript', 'REST APIs', 'Git']::text[], array['TypeScript', 'Docker', 'PostgreSQL']::text[], '', '3 months', 'Active', '', '', true, 1),
    ('postman-fullstack', 'postman', 'Full Stack Engineering Intern', 'Full Stack', 'Bengaluru', 'Hybrid', 3, 28000, 'Join the collaboration team building the workspace features that let millions of developers design and test APIs together. You will work across the stack, from React panels to the Node services behind them.', array['Ship end-to-end features across a React frontend and Node backend.', 'Design and query PostgreSQL schemas for collaboration data.', 'Write API endpoints consumed by the desktop and web clients.']::text[], array['React', 'Node.js', 'REST APIs', 'PostgreSQL']::text[], array['TypeScript', 'Docker']::text[], '', '3 months', 'Active', '', '', true, 2),
    ('myntra-fe', 'myntra', 'Frontend Engineer Intern', 'Frontend', 'Bengaluru', 'Remote', 3, 22000, 'The frontend guild owns the shopping experience used by 50 million people. You will work on the design system and the performance budget that keeps it fast on low-end devices.', array['Contribute components to the shared design system.', 'Profile and reduce bundle size on critical shopping pages.', 'Write accessible markup that works on screen readers.']::text[], array['React', 'TypeScript', 'JavaScript']::text[], array['Next.js', 'GraphQL', 'Testing']::text[], '', '3 months', 'Active', '', '', true, 3),
    ('razorpay-be', 'razorpay', 'Backend Engineering Intern', 'Backend', 'Bangalore', 'Hybrid', 6, 35000, 'Work on the payment rails behind a large share of Indian internet commerce. Backend interns here own real production services with a mentor alongside them.', array['Build and maintain REST services in Node.js.', 'Write and optimise PostgreSQL queries under production load.', 'Add observability to services you own.']::text[], array['Node.js', 'SQL', 'REST APIs', 'Git']::text[], array['Docker', 'Redis', 'Go']::text[], '', '6 months', 'Active', '', '', true, 4),
    ('swiggy-ds', 'swiggy', 'Data Science Intern', 'Data Science', 'Bangalore', 'Hybrid', 6, 30000, 'Join the demand forecasting team. You will get one real problem, one mentor and a dataset large enough that your choices actually matter.', array['Build and evaluate forecasting models in Python.', 'Write SQL against a large event warehouse.', 'Present findings to the operations team every fortnight.']::text[], array['Python', 'SQL', 'Statistics']::text[], array['Pandas', 'Machine Learning', 'Airflow']::text[], '', '6 months', 'Active', '', '', true, 7),
    ('pixelforge-ux', 'pixelforge', 'UI/UX Design Intern', 'UI/UX', 'Remote', 'Remote', 2, 15000, 'A twelve-person studio designing products for early-stage founders. You will sit in on real client work from your first week.', array['Produce wireframes and high-fidelity screens in Figma.', 'Join client calls and take design feedback directly.', 'Maintain the studio component library.']::text[], array['Figma', 'Wireframing']::text[], array['Motion Design', 'Framer']::text[], '', '2 months', 'Active', '', '', true, 8),
    ('zomato-pd', 'zomato', 'Product Design Intern', 'UI/UX', 'Gurgaon', 'On-site', 3, 25000, 'Shape how millions of people decide what to eat. The team is opinionated about motion, typography and the small details of a delivery experience.', array['Design flows for the ordering and tracking experience.', 'Prototype motion and hand off to engineering.', 'Run usability sessions with real users.']::text[], array['Figma', 'Prototyping', 'Interaction Design']::text[], array['Motion Design', 'User Research']::text[], '', '3 months', 'Active', '', '', true, 9),
    ('nexora-be', 'nexora', 'Backend Engineering Intern', 'Backend', 'Bangalore', 'Remote', 3, 18000, 'The platform team keeps the services behind our developer tools fast and boring. You will own a small service end to end, with a mentor reviewing everything you ship.', array['Build REST endpoints in Node.js against a PostgreSQL schema.', 'Write migrations and keep queries under the latency budget.', 'Add tracing to the endpoints you own.']::text[], array['Node.js', 'PostgreSQL', 'REST APIs']::text[], array['Docker', 'Redis']::text[], '', '3 months', 'Active', '', '', true, 6),
    ('flipkart-mobile', 'flipkart', 'Mobile Developer Intern', 'Frontend', 'Bengaluru', 'Hybrid', 6, 26000, 'Build for the widest device range in the world.', array['Ship React Native screens.', 'Profile performance on low-end Android.']::text[], array['React', 'JavaScript', 'React Native']::text[], array['Kotlin', 'TypeScript']::text[], '', '6 months', 'Active', '', '', false, 99),
    ('cred-pd', 'cred', 'Product Design Intern', 'UI/UX', 'Bangalore', 'On-site', 6, 28000, 'An unusually high design bar and a distinctive visual language.', array['Design members-only product surfaces.', 'Prototype interaction detail.']::text[], array['Figma', 'Interaction Design', 'Prototyping', 'Visual Design']::text[], array['Motion Design', 'Swift']::text[], '', '6 months', 'Active', '', '', false, 99),
    ('zepto-be', 'zepto', 'Backend Engineering Intern', 'Backend', 'Mumbai', 'On-site', 3, 24000, 'One of the tightest logistics loops in Indian commerce.', array['Build order routing services.', 'Optimise hot database paths.']::text[], array['Node.js', 'PostgreSQL', 'REST APIs']::text[], array['Redis', 'Docker']::text[], '', '3 months', 'Active', '', '', false, 99),
    ('meesho-fe', 'meesho', 'Frontend Developer Intern', 'Frontend', 'Bengaluru', 'Hybrid', 3, 20000, 'Build for first-time internet shoppers across small-town India.', array['Ship React features on a tight performance budget.']::text[], array['React', 'JavaScript', 'CSS']::text[], array['TypeScript', 'Performance']::text[], '', '3 months', 'Active', '', '', false, 99),
    ('technova-frontend', 'technova', 'Frontend Engineering Intern', 'Frontend', 'Bangalore', 'Hybrid', 3, 35000, 'Join TechNova''s product team to build and refine the UI components powering our AI infrastructure platform. You''ll work directly with senior engineers and our design team, and own a surface end to end by week four.', array['Build and maintain components in our internal design system', 'Ship features to the deployment console used by 4,000 engineers', 'Work with design on handoff, states and accessibility', 'Review pull requests and take part in weekly ship reviews']::text[], array['React', 'TypeScript', 'HTML/CSS', 'Git']::text[], array['Tailwind CSS', 'Figma', 'REST APIs', 'Testing']::text[], 'Engineering', 'Full-time · 10 weeks', 'Active', '12 Mar 2025', '4 Apr 2025', true, 0),
    ('technova-design', 'technova', 'Product Design Intern', 'Design', 'Bangalore', 'On-site', 3, 30000, 'Shape the visual and interaction design of TechNova''s developer tools. Own end-to-end flows from research through final handoff, with a design lead reviewing your work weekly.', array['Run discovery interviews with platform engineers', 'Design flows for the console and take them through handoff', 'Contribute components back to the design system']::text[], array['Figma', 'UX Research', 'Prototyping', 'Design Systems']::text[], array['Framer', 'Motion Design', 'User Testing', 'Copywriting']::text[], 'Design', 'Full-time · 12 weeks', 'Active', '8 Mar 2025', '10 Apr 2025', true, 5),
    ('technova-growth', 'technova', 'Growth Marketing Intern', 'Growth', 'Remote', 'Remote', 2, 20000, 'Drive TechNova''s developer community growth through content, events and organic channels. Own and measure experiments across the full funnel.', array['Write and publish developer-facing content weekly', 'Run and report on growth experiments', 'Support community events and the monthly newsletter']::text[], array['Content Strategy', 'Analytics', 'SEO', 'Social Media']::text[], array['HubSpot', 'Figma', 'A/B Testing', 'Copywriting']::text[], 'Marketing', 'Full-time · 8 weeks', 'Paused', '28 Feb 2025', '25 Mar 2025', false, 99);

  /* ------------------------------ applications ------------------------------ */
  insert into public.applications (student_id, job_id, status, stage, note, note_ai_drafted, resume_file, fit_snapshot, applied_label, applied_order, timeline, availability, preference_notes, resume_summary, created_at) values
    ('arjun-mehta', 'technova-frontend', 'selected', 'Selected', 'I''ve been following TechNova''s open-source work on GitHub — the design system tooling you''re building is exactly the kind of problem I want to work on.', false, 'arjun-mehta-resume-2025.pdf', 98, 'Applied 12 days ago', 1, '[{"status":"applied","date":"14 Mar"},{"status":"reviewing","date":"21 Mar","detail":"Your application is being reviewed by the team."},{"status":"selected","date":"24 Mar","detail":"TechNova selected you."}]'::jsonb, 'May 20 – Aug 15, 2025 · Full-time', array['Bangalore or Hybrid', 'Design-focused engineering', 'Mentorship from seniors']::text[], 'Read against this role: Arjun clears every required skill with shipped work behind it, not coursework. The Razorpay internship is production frontend at payments scale, and Luminate shows he can own a design system rather than just consume one. Testing is the only preferred skill missing. Recommend fast-tracking.', now() - interval '16 days'),
    ('kavya-reddy', 'technova-frontend', 'selected', 'In Conversation', 'I shipped a React Native app at Zomato that''s now in production serving 2M users. I''d love to bring that scale experience to TechNova''s frontend team.', false, 'kavya-reddy-resume-2025.pdf', 86, 'Applied 12 days ago', 2, '[{"status":"applied","date":"14 Mar"},{"status":"reviewing","date":"21 Mar","detail":"Your application is being reviewed by the team."},{"status":"selected","date":"24 Mar","detail":"TechNova selected you."}]'::jsonb, 'Jun 2 – Aug 29, 2025 · Full-time', array['Mumbai or Remote', 'Product-facing engineering']::text[], 'Read against this role: Kavya covers every required skill, and the Zomato internship is the largest production surface in this pool — 2M+ users at final year is rare. She wants remote and you are hybrid in Bangalore, which is the real friction here, not her skills. No test files anywhere in her public work.', now() - interval '15 days'),
    ('rohan-sharma', 'technova-frontend', 'reviewing', 'Reviewed', 'I transitioned from Vue to React in my Nexora internship and found the paradigm shift very natural — the component model carries over well.', false, 'rohan-sharma-bits-2025.pdf', 81, 'Applied 11 days ago', 3, '[{"status":"applied","date":"15 Mar"},{"status":"reviewing","date":"21 Mar","detail":"Your application is being reviewed by the team."}]'::jsonb, 'May 26 – Aug 22, 2025 · Full-time', array['Pune or Hybrid', 'Product-facing work']::text[], 'Read against this role: Rohan has the TypeScript depth and the tooling instincts, but no React in any project — Vue is his framework. The Nexora internship shows he rebuilt a production dashboard in TypeScript, so the transferable half is genuine. Budget roughly two weeks of ramp on React specifically.', now() - interval '14 days'),
    ('ishita-patel', 'technova-frontend', 'reviewing', 'Reviewed', 'I''m passionate about accessible design — I ran a WCAG 2.1 workshop for 120 students at NIT''s tech fest last semester.', false, 'ishita-patel-nit-trichy-2025.pdf', 72, 'Applied 10 days ago', 4, '[{"status":"applied","date":"16 Mar"},{"status":"reviewing","date":"21 Mar","detail":"Your application is being reviewed by the team."}]'::jsonb, 'Jun 16 – Sep 5, 2025 · Full-time', array['Chennai or Bangalore', 'Accessibility or design-systems work']::text[], 'Read against this role: Ishita is the only applicant here who both designs and builds, and her accessibility work is real rather than claimed. TypeScript is the blocker — it is a hard requirement and she has never used it. Her Git is self-declared with no collaborative history behind it. High upside if you can absorb the ramp.', now() - interval '13 days'),
    ('siddharth-nair', 'technova-frontend', 'applied', 'Applied', null, false, 'siddharth-nair-vit-2025.pdf', 56, 'Applied 8 days ago', 5, '[{"status":"applied","date":"18 Mar"}]'::jsonb, 'May 20 – Aug 8, 2025 · Full-time', array['Hyderabad or Remote', 'ML or data-adjacent projects welcome']::text[], 'Read against this role: strong CS fundamentals and genuine ML research, but this is a React and TypeScript role and he has neither. His frontend is vanilla JavaScript. The GPA and the EMNLP submission are impressive in the abstract and largely irrelevant to what this job needs. Better suited to a backend or ML-adjacent opening.', now() - interval '12 days'),
    ('meera-krishnan', 'technova-frontend', 'applied', 'Applied', null, false, 'meera-krishnan-manipal-2025.pdf', 53, 'Applied 7 days ago', 6, '[{"status":"applied","date":"19 Mar"}]'::jsonb, 'Jun 2 – Aug 15, 2025 · Part-time or full-time', array['Bangalore or Remote', 'Flexible schedule']::text[], 'Read against this role: clean fundamentals and a good eye, but no framework experience of any kind and no API work — every project uses static data. Her Git history is solo commits with no branches or reviews. This role needs React and TypeScript from day one. Worth keeping warm for a more junior opening.', now() - interval '11 days'),
    ('dev-joshi', 'technova-frontend', 'applied', 'Applied', null, false, 'dev-joshi-du-2025.pdf', 26, 'Applied 6 days ago', 7, '[{"status":"applied","date":"20 Mar"}]'::jsonb, 'Jun 2 – Aug 29, 2025 · Full-time', array['Delhi NCR or Remote', 'Business and tech intersection']::text[], 'Read against this role: Dev has real commercial instincts and presented to VP-level stakeholders at Swiggy as an intern, which is unusual. None of it is engineering. No JavaScript, no framework, no version control. This is a mis-application rather than a weak candidate — worth forwarding to whoever owns your product or growth openings.', now() - interval '10 days'),
    ('anika-sharma', 'technova-frontend', 'applied', 'Applied', 'I have shipped two React and TypeScript projects — MediTrack runs a real scheduling API, and SketchSync handles concurrent edits over WebSockets. Owning a surface end to end is exactly the internship I am looking for.', true, 'Anika_Sharma_Resume.pdf', 78, 'Applied 2 days ago', 4, '[{"status":"applied","date":"4 Sep"}]'::jsonb, 'May 19 – Aug 15, 2026 · Full-time', array['Bengaluru or Hybrid', 'Frontend or full-stack work', 'Mentored, production surfaces']::text[], 'Read against this role: Anika clears React, TypeScript and Git with shipped work behind each — MediTrack is a full-stack scheduling app with a real API, and SketchSync is concurrent editing over WebSockets. HTML/CSS is implicit in that work rather than claimed, and Testing is the one preferred skill with nothing behind it. The Frappe internship was production React on a design-system team, which is the closest analogue to this role in the pool.', now() - interval '2 days'),
    ('anika-sharma', 'zepto-be', 'shortlisted', 'Reviewed', 'My MediTrack project is a Node and PostgreSQL service handling real scheduling load — close to the routing work described here.', true, 'Anika_Sharma_Resume.pdf', 76, 'Applied 9 days ago', 1, '[{"status":"applied","date":"27 Aug"},{"status":"reviewing","date":"29 Aug","detail":"Your application is being reviewed by the team."},{"status":"shortlisted","date":"2 Sep","detail":"You are in the top 12% of applicants."}]'::jsonb, 'May 19 – Aug 15, 2026 · Full-time', array['Bengaluru or Hybrid', 'Frontend or full-stack work']::text[], '', now() - interval '11 days'),
    ('anika-sharma', 'flipkart-mobile', 'reviewing', 'Applied', null, false, 'Anika_Sharma_Resume.pdf', 69, 'Applied 6 days ago', 2, '[{"status":"applied","date":"30 Aug"},{"status":"reviewing","date":"1 Sep","detail":"Your application is being reviewed by the team."}]'::jsonb, 'May 19 – Aug 15, 2026 · Full-time', array['Bengaluru or Hybrid', 'Frontend or full-stack work']::text[], '', now() - interval '10 days'),
    ('anika-sharma', 'meesho-fe', 'reviewing', 'Applied', 'I have shipped two React projects and interned on a design-system team, which matches the component work in this role.', true, 'Anika_Sharma_Resume.pdf', 72, 'Applied 4 days ago', 3, '[{"status":"applied","date":"1 Sep"},{"status":"reviewing","date":"3 Sep"}]'::jsonb, 'May 19 – Aug 15, 2026 · Full-time', array['Bengaluru or Hybrid', 'Frontend or full-stack work']::text[], '', now() - interval '9 days'),
    ('anika-sharma', 'cred-pd', 'rejected', 'Reviewed', null, false, 'Anika_Sharma_Resume.pdf', 23, 'Applied 11 days ago', 0, '[{"status":"applied","date":"25 Aug"},{"status":"reviewing","date":"26 Aug"},{"status":"rejected","date":"30 Aug","detail":"They moved forward with candidates who had more visual design work."}]'::jsonb, 'May 19 – Aug 15, 2026 · Full-time', array['Bengaluru or Hybrid', 'Frontend or full-stack work']::text[], '', now() - interval '12 days');

  /* --------------------------------- swipes --------------------------------- */
  insert into public.swipes (student_id, job_id, action) values
    ('anika-sharma', 'myntra-fe', 'saved'),
