  /* ---------------------- selections, threads, messages ---------------------- */
  -- Written in the same order `select_candidate()` writes them: an application is
  -- selected, that selection opens a conversation, and the company speaks first.

  select id into v_app_id from public.applications where student_id = 'arjun-mehta' and job_id = 'technova-frontend';
  insert into public.selections (application_id, student_id, job_id, company_id, selected_by, created_at)
  values (v_app_id, 'arjun-mehta', 'technova-frontend', 'technova', 'priya-sharma', now() - interval '30 hours')
  returning id into v_sel_id;
  insert into public.conversations (selection_id, created_at)
  values (v_sel_id, now() - interval '30 hours') returning id into v_conv_id;
  -- One statement per message: the trigger on `messages` checks whether the thread
  -- already has a row, so each insert must be able to see the one before it.
  insert into public.messages (conversation_id, from_company, body, read_by_student, read_by_company, created_at)
  values (v_conv_id, true, 'Hi Arjun! Congratulations — you''ve been selected for the Frontend Engineering Intern role at TechNova. We were really impressed by your React and design-systems work, especially the Luminate project. I''d love to set up an intro call to walk you through the team and next steps. Are you free this week?', true, true, now() - interval '29 hours');
  insert into public.messages (conversation_id, from_company, body, read_by_student, read_by_company, created_at)
  values (v_conv_id, false, 'Hi Priya! Thank you so much — I''m really excited about TechNova! Yes, I''m available this week. I''m free Thursday afternoon or Friday morning. What works for the team?', true, true, now() - interval '27 hours');
  insert into public.messages (conversation_id, from_company, body, read_by_student, read_by_company, created_at)
  values (v_conv_id, true, 'Thursday works great! Does 2pm IST suit you? We''ll send a Google Meet link ahead of time.', true, true, now() - interval '4 hours');
  insert into public.messages (conversation_id, from_company, body, read_by_student, read_by_company, created_at)
  values (v_conv_id, false, 'Thursday at 2pm IST works perfectly for me!', true, false, now() - interval '12 minutes');

  select id into v_app_id from public.applications where student_id = 'kavya-reddy' and job_id = 'technova-frontend';
  insert into public.selections (application_id, student_id, job_id, company_id, selected_by, created_at)
  values (v_app_id, 'kavya-reddy', 'technova-frontend', 'technova', 'priya-sharma', now() - interval '9 hours')
  returning id into v_sel_id;
  insert into public.conversations (selection_id, created_at)
  values (v_sel_id, now() - interval '9 hours') returning id into v_conv_id;
  -- One statement per message: the trigger on `messages` checks whether the thread
  -- already has a row, so each insert must be able to see the one before it.
  insert into public.messages (conversation_id, from_company, body, read_by_student, read_by_company, created_at)
  values (v_conv_id, true, 'Hi Kavya! We really enjoyed reviewing your work — the Zomato internship stood out strongly. We''d love to have a conversation about the Frontend Engineering Intern role. Are you available for a quick intro call this week?', true, true, now() - interval '8 hours');
  insert into public.messages (conversation_id, from_company, body, read_by_student, read_by_company, created_at)
  values (v_conv_id, false, 'Hi Priya! Absolutely — I''ve been following TechNova for a while and would love to learn more. I''m quite flexible this week. What times work for the team?', true, true, now() - interval '7 hours');
  insert into public.messages (conversation_id, from_company, body, read_by_student, read_by_company, created_at)
  values (v_conv_id, true, 'How about Wednesday at 11am IST? We can do a relaxed 30-minute chat with our engineering lead.', true, true, now() - interval '6 hours');
  insert into public.messages (conversation_id, from_company, body, read_by_student, read_by_company, created_at)
  values (v_conv_id, false, 'Wednesday at 11am IST is perfect. Looking forward to connecting with the team.', true, true, now() - interval '75 minutes');

  /* ------------------------------ notifications ------------------------------ */
  insert into public.notifications (student_id, kind, title, body, time_label, group_label, unread, sort_order) values
    ('anika-sharma', 'status', 'Your Zepto application was shortlisted', 'You are in the top 12% of applicants for Backend Engineering Intern.', '2 h ago', 'Today', true, 3),
    ('anika-sharma', 'view', 'A company viewed your profile', 'Someone at a Series A startup spent 2+ minutes on your profile today.', '5 h ago', 'Today', true, 2),
    ('anika-sharma', 'matches', '5 new internships match your profile', 'Including roles at Nexora Labs, Postman and Myntra — all above 80% fit.', 'Yesterday, 4:12 PM', 'Yesterday', false, 1);

  return format(
    'demo reset · %s companies · %s students · %s jobs · %s applications · %s selections · %s conversations · %s messages',
    (select count(*) from public.companies),
    (select count(*) from public.students),
    (select count(*) from public.jobs),
    (select count(*) from public.applications),
    (select count(*) from public.selections),
    (select count(*) from public.conversations),
    (select count(*) from public.messages)
  );
end;
$seed$;

-- Demo-only: the reset is callable with the publishable key so a presenter can
-- restore the dataset from the app or a one-line script. Revoke this before the
-- project holds anything real.
revoke all on function public.demo_reset() from public;
grant execute on function public.demo_reset() to anon, authenticated;

select public.demo_reset();
